for r in range(len(test_grid)):
    rows_count[r] = sum(1 for pos in twos if pos[0] == r)

cols_count = {}
for c in range(len(test_grid[0])):
    cols_count[c] = sum(1 for pos in twos if pos[1] == c)

print("Test row counts:", rows_count)
print("Test col counts:", cols_count)

# Result according to rule
result = [row[:] for row in test_grid]

